 for(int i=0;i<6500&&!(bool)Property(current,"Finished");i++)Call(current,"Tick",1f/60);var s=State(current);row.final=JsonUtility.ToJson(s);var sim=Property(current,"ReviewSimulation");row.extraSubsteps=Convert.ToInt32(Property(sim,"AdaptiveFloorSubsteps"));row.minBottom=F(sim,"MinBottom");save();if(adaptive){Assert.That((string)Field(s,"physicsFault"),Is.Empty,row.id);Assert.That((bool)Property(current,"Finished"),Is.True);CaptureRoute(row.id,"result");}Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
